+    if metric["pending"] != 0:
+        failures.append(f"pending_events={metric['pending']}")
+    if metric["correction_p99_ns"] >= 16_670_000:
+        failures.append(f"correction_p99_ns={metric['correction_p99_ns']}")
+    if metric["correction_max_ns"] >= 33_340_000:
