+            "presentation_failures", "journal_duplicates",
+            "journal_publish_failures"):
+        if metric[field] != 0:
+            failures.append(f"{field}={metric[field]}")
+    if failures:
+        raise RuntimeError(
+            f"{label} terminal owned metric failure: {', '.join(failures)}")
